// Extract ticket title and description from incoming webhook
const body = $input.item.json.body || $input.item.json;
const title = (body.title || '').toLowerCase();
const description = (body.description || '').toLowerCase();
const text = `${title} ${description}`;

// 1. Determine Category
let categoryCode = 'OTHER';
if (text.includes('payment') || text.includes('refund') || text.includes('deduct') || text.includes('invoice') || text.includes('charge')) {
  categoryCode = 'PAYMENT';
} else if (text.includes('login') || text.includes('password') || text.includes('account') || text.includes('profile')) {
  categoryCode = 'ACCOUNT';
} else if (text.includes('bug') || text.includes('error') || text.includes('crash') || text.includes('exception') || text.includes('code')) {
  categoryCode = 'TECHNICAL';
} else if (text.includes('security') || text.includes('phishing') || text.includes('hack') || text.includes('suspicious')) {
  categoryCode = 'SECURITY';
} else if (text.includes('order') || text.includes('item') || text.includes('purchase')) {
  categoryCode = 'ORDER';
} else if (text.includes('delivery') || text.includes('ship') || text.includes('tracking') || text.includes('parcel')) {
  categoryCode = 'DELIVERY';
}

// 2. Determine Priority
let priority = 'MEDIUM';
if (text.includes('outage') || text.includes('down') || text.includes('critical') || text.includes('production')) {
  priority = 'CRITICAL';
} else if (text.includes('urgent') || text.includes('fail') || text.includes('deducted') || text.includes('cannot access')) {
  priority = 'HIGH';
} else if (text.includes('minor') || text.includes('cosmetic') || text.includes('slow')) {
  priority = 'LOW';
}

// 3. Determine Sentiment
let sentiment = 'NEUTRAL';
if (text.includes('terrible') || text.includes('angry') || text.includes('failed') || text.includes('deducted') || text.includes('worst')) {
  sentiment = 'NEGATIVE';
} else if (text.includes('great') || text.includes('thanks') || text.includes('love')) {
  sentiment = 'POSITIVE';
}

// 4. Generate AI Suggested Response Hint
let suggestedResponse = 'Investigate ticket details and contact customer.';
if (categoryCode === 'PAYMENT') {
  suggestedResponse = 'We apologize for the inconvenience. A refund reconciliation check has been logged. If unverified within 2 hours, funds will be automatically credited.';
} else if (categoryCode === 'ACCOUNT') {
  suggestedResponse = 'Verify user email identity and initiate password reset link if requested.';
} else if (categoryCode === 'TECHNICAL') {
  suggestedResponse = 'Check application logs around the failure timestamp and request stack trace if needed.';
}

return {
  json: {
    categoryCode,
    priority,
    sentiment,
    suggestedResponse
  }
};
